/* @lc app=leetcode id=2537 lang=kotlin */ class Solution { fun countGood(nums: IntArray, k: Int): Long = HashMap<Int, Int>().let { c -> nums.indices.fold(Triple(0, 0L, 0L)) { (r, p, ans), l -> generateSequence(r to p) { (rr, pp) -> if (pp >= k || rr == nums.size) null else (c.merge(nums[rr], 1) { a, b -> a + b }!! - 1).let { rr + 1 to pp + it } }.last().let { (r2, p2) -> Triple(r2, p2 - c.merge(nums[l], -1) { a, b -> a + b }!!, ans + if (p2 >= k) nums.size - r2 + 1 else 0) } }.third } }